#!/usr/bin/env python3

"""
Reproduction script for the annotated types serialization_strategy issue.
"""

from dataclasses import dataclass
from typing import Annotated, TypeAlias
from mashumaro import DataClassDictMixin


# Define annotated types
PositiveInt: TypeAlias = Annotated[int, "PositiveInt"]
NegativeInt: TypeAlias = Annotated[int, "NegativeInt"]


def deserialize_positive_int(value):
    print(f"Deserializing positive int: {value}")
    if value < 0:
        raise ValueError("value < 0")
    return value


def deserialize_negative_int(value):
    print(f"Deserializing negative int: {value}")
    if value >= 0:
        raise ValueError("value >= 0")
    return value


def serialize_positive_int(value):
    print(f"Serializing positive int: {value}")
    if value < 0:
        raise ValueError("value < 0")
    return value


def serialize_negative_int(value):
    print(f"Serializing negative int: {value}")
    if value >= 0:
        raise ValueError("value >= 0")
    return value


@dataclass
class MyClass(DataClassDictMixin):
    positive_int: PositiveInt
    negative_int: NegativeInt

    class Config:
        serialization_strategy = {
            PositiveInt: {
                "deserialize": deserialize_positive_int,
                "serialize": serialize_positive_int,
            },
            NegativeInt: {
                "deserialize": deserialize_negative_int,
                "serialize": serialize_negative_int,
            }
        }


def test_basic_functionality():
    """Test that basic functionality works."""
    print("=== Testing Basic Functionality ===")

    # Test creation
    obj = MyClass(positive_int=5, negative_int=-3)
    print(f"Created object: {obj}")

    # Test serialization
    try:
        serialized = obj.to_dict()
        print(f"Serialized: {serialized}")
    except Exception as e:
        print(f"Serialization failed: {e}")
        return False

    # Test deserialization
    try:
        deserialized = MyClass.from_dict({"positive_int": 10, "negative_int": -7})
        print(f"Deserialized: {deserialized}")
    except Exception as e:
        print(f"Deserialization failed: {e}")
        return False

    return True


def test_strategy_application():
    """Test that custom strategies are actually applied."""
    print("\n=== Testing Strategy Application ===")

    # Test that strategies are called during deserialization
    try:
        obj = MyClass.from_dict({"positive_int": -5, "negative_int": -10})
        print(f"Should have failed but got: {obj}")
        return False  # Should have raised ValueError
    except ValueError as e:
        print(f"Correctly caught error during deserialization: {e}")
    except Exception as e:
        print(f"Unexpected error during deserialization: {e}")
        return False

    # Test that strategies are called during serialization
    try:
        obj = MyClass(positive_int=-5, negative_int=-10)  # Invalid values
        serialized = obj.to_dict()
        print(f"Should have failed but got: {serialized}")
        return False  # Should have raised ValueError
    except ValueError as e:
        print(f"Correctly caught error during serialization: {e}")
    except Exception as e:
        print(f"Unexpected error during serialization: {e}")
        return False

    return True


if __name__ == "__main__":
    success = test_basic_functionality()
    if success:
        success = test_strategy_application()

    if success:
        print("\n✓ All tests passed!")
    else:
        print("\n✗ Tests failed!")
        exit(1)

