#!/usr/bin/env python3

"""
Test to understand how annotated types with serialization strategies should work.
"""

from dataclasses import dataclass
from datetime import date
from typing import Annotated

from mashumaro import DataClassDictMixin


def test_annotated_with_custom_strategies():
    """Test annotated types with custom dict-based serialization strategies."""

    PositiveInt = Annotated[int, "PositiveInt"]
    NegativeInt = Annotated[int, "NegativeInt"]

    def deserialize_positive_int(value):
        print(f"DESERIALIZE Positive: {value}")
        if value < 0:
            raise ValueError("Expected positive int")
        return value

    def deserialize_negative_int(value):
        print(f"DESERIALIZE Negative: {value}")
        if value >= 0:
            raise ValueError("Expected negative int")
        return value

    def serialize_positive_int(value):
        print(f"SERIALIZE Positive: {value}")
        if value < 0:
            raise ValueError("Expected positive int")
        return value

    def serialize_negative_int(value):
        print(f"SERIALIZE Negative: {value}")
        if value >= 0:
            raise ValueError("Expected negative int")
        return value

    @dataclass
    class MyDataClass(DataClassDictMixin):
        pos: PositiveInt
        neg: NegativeInt

        class Config:
            serialization_strategy = {
                PositiveInt: {
                    "deserialize": deserialize_positive_int,
                    "serialize": serialize_positive_int,
                },
                NegativeInt: {
                    "deserialize": deserialize_negative_int,
                    "serialize": serialize_negative_int,
                }
            }

    # Test deserialization
    print("=== Testing deserialization ===")
    obj = MyDataClass.from_dict({"pos": 5, "neg": -3})
    print(f"Success: {obj}")

    # Test serialization  
    print("\n=== Testing serialization ===")
    result = obj.to_dict()
    print(f"Result: {result}")

    # Test error cases
    print("\n=== Testing error cases ===")
    try:
        MyDataClass.from_dict({"pos": -5, "neg": -3})
        print("ERROR: Should have failed!")
    except ValueError as e:
        print(f"Correctly caught deserialization error: {e}")

    try:
        bad_obj = MyDataClass(pos=-5, neg=-3)
        bad_obj.to_dict()
        print("ERROR: Should have failed!")
    except ValueError as e:
        print(f"Correctly caught serialization error: {e}")


if __name__ == "__main__":
    test_annotated_with_custom_strategies()

